import{_ as a,y as n,a as r,o,a2 as s,D as i,g as l}from"./chunks/framework.DCcmcJcL.js";const w=JSON.parse('{"title":"Review Translation","description":"","frontmatter":{},"headers":[],"relativePath":"generative-ai/review-translation.md","filePath":"generative-ai/review-translation.md","lastUpdated":1789395222000}'),h={name:"generative-ai/review-translation.md"};function g(p,e,c,d,u,v){const t=n("ImagePopup");return o(),r("div",null,[e[0]||(e[0]=s('<h1 id="review-translation" tabindex="-1">Review Translation <a class="header-anchor" href="#review-translation" aria-label="Permalink to &quot;Review Translation&quot;">​</a></h1><div class="feature-meta feature--ai"><span class="feature-meta__primary">Generative AI</span><span>Storefront</span></div><p>With review translation on, a <strong>Translate</strong> link appears under each product review on the storefront. Clicking it shows the review in the language of the store the shopper is browsing, so a review written in another language is still useful to them. The review itself is not changed; the translation is made when the shopper asks for it.</p><h2 id="turning-it-on" tabindex="-1">Turning it on <a class="header-anchor" href="#turning-it-on" aria-label="Permalink to &quot;Turning it on&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Magic AI &gt;&gt; Storefront Features</strong>. If your store has more than one channel, choose the channel at the top of the page.</li><li>In the <strong>Review Translation</strong> section, switch <strong>Enabled</strong> on.</li><li>Choose the <strong>Model</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol><p>The API key of the chosen model&#39;s provider must be saved first; see <a href="./../configure/magic-ai.html">Generative AI Configuration</a>. Unlike the other storefront features, review translation is controlled by this switch alone and keeps working when the general <strong>Enabled</strong> switch is off.</p><h2 id="what-the-shopper-sees" tabindex="-1">What the shopper sees <a class="header-anchor" href="#what-the-shopper-sees" aria-label="Permalink to &quot;What the shopper sees&quot;">​</a></h2><ol><li>The shopper opens a product page and scrolls to its reviews.</li><li>Under a review, they click <strong>Translate</strong>. The link reads <strong>Translating...</strong> while the model works, and the translated text then replaces the original.</li></ol>',8)),i(t,{src:"/images/generative-ai/review-magicai.png",alt:"Translate link under a review"}),e[1]||(e[1]=l("p",null,"The translation is into the locale the shopper has selected in the storefront, so a store that serves several languages translates each review into whichever one the visitor is using.",-1))])}const m=a(h,[["render",g]]);export{w as __pageData,m as default};
